package com.coffeeshop.service;import com.coffeeshop.dto.PurchasingCommands;import com.coffeeshop.model.PurchasingModels;import com.coffeeshop.repository.PurchasingRepository;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class PurchasingServiceTest{private final Stub repo=new Stub();private final PurchasingService service=new PurchasingService(repo);@Test void validatesAndNormalizesSupplier(){service.saveSupplier(new PurchasingCommands.Supplier(null," S01 "," Beans Ltd ",null,null,"sales@example.com",null,null,true,null));assertEquals("S01",repo.supplier.code());assertEquals("Beans Ltd",repo.supplier.name());}@Test void updateSupplierRequiresVersion(){assertThrows(IllegalArgumentException.class,()->service.saveSupplier(new PurchasingCommands.Supplier(1L,"S","Supplier",null,null,null,null,null,true,null)));}@Test void draftCalculatesAndValidatesLines(){service.saveDraft(purchase(List.of(line(1,"2.5000","3.0000")),"1.0000","0.5000"),7);assertEquals(1,repo.purchase.items().size());assertEquals(new BigDecimal("2.5000"),repo.purchase.items().getFirst().quantity());}@Test void rejectsDuplicateAndInvalidLines(){assertThrows(IllegalArgumentException.class,()->service.saveDraft(purchase(List.of(line(1,"1","1"),line(1,"2","1")),"0","0"),7));assertThrows(IllegalArgumentException.class,()->service.saveDraft(purchase(List.of(line(1,"0","1")),"0","0"),7));assertThrows(IllegalArgumentException.class,()->service.saveDraft(purchase(List.of(line(1,"1","-1")),"0","0"),7));}@Test void onlyDraftMayReceiveOrCancel(){PurchasingModels.Purchase p=model("RECEIVED");assertThrows(IllegalStateException.class,()->service.receive(p,1));assertThrows(IllegalStateException.class,()->service.cancel(p));}@Test void delegatesReceiveAndCancelWithVersion(){PurchasingModels.Purchase p=model("DRAFT");service.receive(p,4);service.cancel(p);assertEquals(1,repo.received);assertEquals(1,repo.cancelled);}private static PurchasingCommands.Line line(long id,String q,String c){return new PurchasingCommands.Line(null,id,new BigDecimal(q),new BigDecimal(c),null);}private static PurchasingCommands.Purchase purchase(List<PurchasingCommands.Line>l,String d,String t){return new PurchasingCommands.Purchase(null,1,LocalDateTime.now(),new BigDecimal(d),new BigDecimal(t),null,null,l,null);}private static PurchasingModels.Purchase model(String status){return new PurchasingModels.Purchase(1,"P1",1,"S",LocalDateTime.now(),status,BigDecimal.ONE,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ONE,null,null,new byte[]{1},List.of());}private static final class Stub implements PurchasingRepository{PurchasingCommands.Supplier supplier;PurchasingCommands.Purchase purchase;int received,cancelled;public PurchasingModels.Catalog load(){return new PurchasingModels.Catalog(List.of(),List.of(),List.of());}public long saveSupplier(PurchasingCommands.Supplier q){supplier=q;return 1;}public void setSupplierActive(long id,boolean a,byte[]v){}public long saveDraft(PurchasingCommands.Purchase q,long u){purchase=q;return 1;}public void receive(long id,long u,byte[]v){received++;}public void cancel(long id,byte[]v){cancelled++;}}}
